#!/bin/bash
# Uninstall script for OBS
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling OBS..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping OBS if running..."
pkill -f "OBS" 2>/dev/null || true

# Remove /Applications/OBS.app
echo "Removing /Applications/OBS.app..."
if [ -d "/Applications/OBS.app" ]; then
    rm -rf "/Applications/OBS.app" 2>/dev/null || true
elif [ -f "/Applications/OBS.app" ]; then
    rm -f "/Applications/OBS.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/obs-studio
echo "Removing $HOME/Library/Application Support/obs-studio..."
if [ -d "$HOME/Library/Application Support/obs-studio" ]; then
