fi

# Remove $HOME/Library/Saved Application State/com.obsproject.obs-studio.savedState
echo "Removing $HOME/Library/Saved Application State/com.obsproject.obs-studio.savedState..."
if [ -d "$HOME/Library/Saved Application State/com.obsproject.obs-studio.savedState" ]; then
